// Feriados = nacionais (BrasilAPI) + feriados locais + folgas pessoais. Ajuste as 4 constantes abaixo.
const FOLGAS_EXTRAS = [ /* 'AAAA-MM-DD', ... folgas/emendas pessoais */ ];
const FERIADOS_LOCAIS_FIXOS = [ /* ['MM-DD', 'Nome'], ex.: ['01-25', 'Aniversário de São Paulo'] */ ];
const CARNAVAL_E_FERIADO = false;      // segunda/terça de Carnaval
const CINZAS_E_FERIADO = true;         // Quarta-feira de Cinzas

let manual = false;
try { manual = $('Teste manual').isExecuted; } catch (e) {}
const now = DateTime.now().setZone('America/Sao_Paulo');
const today = now.startOf('day');
const y = today.year;

function easter(year) {
  const a = year % 19, b = Math.floor(year / 100), c = year % 100, d = Math.floor(b / 4), e = b % 4;
  const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451), month = Math.floor((h + l - 7 * m + 114) / 31);
  const day = ((h + l - 7 * m + 114) % 31) + 1;
  return DateTime.fromObject({ year, month, day }, { zone: 'America/Sao_Paulo' });
}

const hol = {};
for (const it of $input.all()) {
  const h = it.json;
  if (h && h.date && (CARNAVAL_E_FERIADO || !/carnaval/i.test(h.name || ''))) hol[h.date] = h.name;
}
for (const yy of [y, y + 1]) {
  const e = easter(yy);
  if (CINZAS_E_FERIADO) hol[e.minus({ days: 46 }).toISODate()] = 'Quarta-feira de Cinzas';
  hol[e.minus({ days: 2 }).toISODate()] ||= 'Sexta-feira Santa';
  hol[e.plus({ days: 60 }).toISODate()] ||= 'Corpus Christi';
  for (const [md, nome] of FERIADOS_LOCAIS_FIXOS) hol[yy + '-' + md] = nome;
  hol[yy + '-01-01'] ||= 'Confraternização Universal';
  hol[yy + '-12-25'] ||= 'Natal';
}
for (const d of FOLGAS_EXTRAS) hol[d] = 'Folga pessoal';

const isOff = (d) => d.weekday >= 6 || !!hol[d.toISODate()];
let next = today.plus({ days: 1 });
while (isOff(next)) next = next.plus({ days: 1 });
let prev = today.minus({ days: 1 });
while (isOff(prev)) prev = prev.minus({ days: 1 });

return [{ json: {
  today: today.toISODate(),
  is_holiday: manual ? false : isOff(today),
  test: manual,
  holiday_name: hol[today.toISODate()] || null,
  next_business_day: next.toISODate(),
  prev_business_day: prev.toISODate(),
  window_start: today.toISO(),
  window_end: next.endOf('day').toISO(),
} }];

const cal = $('Calendário útil (feriados)').first().json;
const st = $input.first().json || {};
let cutoff = st.last_run ? DateTime.fromISO(st.last_run) : DateTime.fromISO(cal.prev_business_day, { zone: 'America/Sao_Paulo' }).set({ hour: 6, minute: 30 });
const floor = DateTime.now().minus({ days: 4 });
if (cutoff < floor) cutoff = floor;
return [{ json: { ...cal, cutoff_iso: cutoff.toISO(), cutoff_epoch: Math.floor(cutoff.toSeconds()) } }];

const cals = ($input.first().json.items || []).filter(c => !c.deleted);
if (!cals.length) return [{ json: { id: 'primary', summary: 'Pessoal' } }];
return cals.map(c => ({ json: { id: c.id, summary: c.summaryOverride || c.summary } }));

const J = $('Janela de novidade').first().json;
const cutoff = DateTime.fromISO(J.cutoff_iso);
const safe = (name) => { try { return $(name).all().map(i => i.json).filter(x => x && Object.keys(x).length && !x.error); } catch (e) { return []; } };
const errs = (name) => { try { return $(name).all().map(i => i.json).filter(x => x && x.error).map(x => String(x.error.message || x.error).slice(0, 200)); } catch (e) { return []; } };
const cut = (s, n) => (s || '').replace(/\s+/g, ' ').trim().slice(0, n);

// Calendário
const calNames = safe('Calendários a consultar');
const eventos = [];
safe('Google Calendar: eventos').forEach((r, idx) => {
  const cal = r.summary || (calNames[idx] || {}).summary;
  (r.items || []).forEach(e => {
    if (e.status === 'cancelled') return;
    eventos.push({ calendario: cal, titulo: e.summary, inicio: e.start && (e.start.dateTime || e.start.date),
      fim: e.end && (e.end.dateTime || e.end.date), local: e.location, descricao: cut(e.description, 300),
      meet: e.hangoutLink || undefined });
  });
});

// TickTick
const projName = {};
safe('Projetos TickTick').forEach(p => projName[p.id] = p.name);
const limite = DateTime.fromISO(J.window_end);
const tarefas = [];
safe('TickTick: tarefas').forEach(r => (r.tasks || []).forEach(t => {
  if (t.status !== 0) return;
  const due = t.dueDate ? DateTime.fromISO(t.dueDate.replace(/([+-]\d{2})(\d{2})$/, '$1:$2')) : null;
  if (!due || due > limite) return;
  tarefas.push({ titulo: t.title, projeto: projName[t.projectId] || (r.project && r.project.name) || 'Inbox',
    vencimento: due.setZone('America/Sao_Paulo').toISO(), dia_inteiro: !!t.isAllDay,
    atrasada: due < DateTime.fromISO(J.window_start), prioridade: t.priority, conteudo: cut(t.content || t.desc, 200) });
}));

// Gmail
const emails = safe('Gmail: não lidos').filter(m => m.Subject || m.From).map(m => ({ de: m.From, assunto: m.Subject, trecho: cut(m.snippet, 300),
  data: m.internalDate ? DateTime.fromMillis(+m.internalDate).toISO() : undefined,
  link: m.threadId ? 'https://mail.google.com/mail/u/0/#inbox/' + m.threadId : undefined }));
const financas = safe('Gmail: análises financeiras').filter(m => m.subject || m.Subject).map(m => ({ de: (m.from && m.from.text) || m.From, assunto: m.subject || m.Subject,
  data: m.date, texto: cut(m.text, 5000), link: m.threadId ? 'https://mail.google.com/mail/u/0/#all/' + m.threadId : undefined }));

// RSS: só o que é posterior ao corte, até 6 por fonte
const feedsList = safe('Lista de feeds RSS');
const hostToFonte = {};
feedsList.forEach(f => { try { hostToFonte[new URL(f.url).hostname.replace(/^www\./, '')] = f.fonte; } catch (e) {} });
const porFonte = {};
safe('RSS: ler feeds').forEach(it => {
  const d = it.isoDate ? DateTime.fromISO(it.isoDate) : null;
  if (!it.link || !d || d <= cutoff) return;
  let host = ''; try { host = new URL(it.link).hostname.replace(/^www\./, ''); } catch (e) {}
  const match = Object.entries(hostToFonte).find(([h]) => host === h || host.endsWith('.' + h));
  const fonte = match ? match[1] : host;
  (porFonte[fonte] ||= []).push({ titulo: it.title, link: it.link, data: d.toISO(), resumo: cut(it.contentSnippet || it.content, 280) });
});
const noticias = Object.fromEntries(Object.entries(porFonte).map(([k, v]) => [k, v.sort((a, b) => b.data.localeCompare(a.data)).slice(0, 6)]));

const org = (safe('Organizze: pagamentos (Postgres)')[0] || {}).organizze || null;

// Tempo (Open-Meteo)
const WMO = {0:'céu limpo',1:'predominantemente limpo',2:'parcialmente nublado',3:'nublado',45:'neblina',48:'neblina com geada',
  51:'garoa fraca',53:'garoa',55:'garoa forte',56:'garoa congelante',57:'garoa congelante forte',61:'chuva fraca',63:'chuva',65:'chuva forte',
  66:'chuva congelante',67:'chuva congelante forte',71:'neve fraca',73:'neve',75:'neve forte',77:'grãos de neve',80:'pancadas de chuva fracas',
  81:'pancadas de chuva',82:'pancadas de chuva fortes',85:'pancadas de neve',86:'pancadas de neve fortes',95:'trovoadas',96:'trovoadas com granizo',99:'trovoadas com granizo forte'};
let tempo = null;
const w = safe('Previsão do tempo (Open-Meteo)')[0];
if (w && w.daily && w.hourly) {
  const dia = (date) => { const i = w.daily.time.indexOf(date); if (i < 0) return null;
    return { data: date, condicao: WMO[w.daily.weather_code[i]], minima_c: w.daily.temperature_2m_min[i], maxima_c: w.daily.temperature_2m_max[i],
      chance_chuva_pct: w.daily.precipitation_probability_max[i], chuva_mm: w.daily.precipitation_sum[i],
      vento_max_kmh: w.daily.wind_speed_10m_max[i], uv_max: w.daily.uv_index_max[i] }; };
  const horas = w.hourly.time.map((t, k) => ({ hora: t.slice(11, 16), temp_c: w.hourly.temperature_2m[k],
      chance_chuva_pct: w.hourly.precipitation_probability[k], condicao: WMO[w.hourly.weather_code[k]], _d: t.slice(0, 10) }))
    .filter(h => h._d === J.today && ['07:00','09:00','12:00','15:00','18:00','21:00'].includes(h.hora)).map(({ _d, ...h }) => h);
  tempo = { local: 'São Paulo', /* ajuste junto com lat/lon do nó de previsão */ hoje: dia(J.today), amanha: dia(J.next_business_day) || dia(w.daily.time[1]), ao_longo_de_hoje: horas };
}


return [{ json: {
  date: J.today,
  cutoff: J.cutoff_iso,
  test: !!J.test,
  data: {
    hoje: J.today,
    proximo_dia_util: J.next_business_day,
    previsao_tempo: tempo,
    agenda: eventos,
    tarefas_ticktick: tarefas,
    pagamentos_organizze: org,
    emails_nao_lidos: emails,
    emails_financas: financas,
    feeds: noticias,
    newsletters_web: ['The News', 'The News Money', 'The News Sports', 'TheJobs', 'Filipe Deschamps'],
    fontes_com_erro: {
      gmail: errs('Gmail: não lidos'), calendario: errs('Google Calendar: calendários'),
      ticktick: errs('TickTick: projetos'), tempo: errs('Previsão do tempo (Open-Meteo)'), organizze: errs('Organizze: pagamentos (Postgres)'),
    },
  },
} }];
